import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是低库存阈值配置相对于仓库根目录的路径。
var thresholdsFile = filepath.Join("config", "thresholds.json")

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 config/thresholds.json 里该仓库的配置；未配置、文件缺失、
// 读不出来或内容不是 JSON 对象时，一律回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := configuredThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// configuredThresholds 读取并解析阈值配置，失败时返回 nil。
func configuredThresholds() map[string]int {
	data, err := os.ReadFile(findThresholdsFile())
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// findThresholdsFile 定位阈值配置：从当前目录逐级向上找，
// 这样无论从仓库根还是从包目录运行都能找到同一份文件。
func findThresholdsFile() string {
	dir, err := os.Getwd()
	if err == nil {
		for {
			candidate := filepath.Join(dir, thresholdsFile)
			if _, err := os.Stat(candidate); err == nil {
				return candidate
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
	}
	return thresholdsFile
}

