	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("unconfigured = %d, want %d", got, DefaultLowStockThreshold)
	}

	write(`not json`)
	if got := LowStockThreshold("testwh"); got != DefaultLowStockThreshold {
		t.Fatalf("invalid json = %d, want %d", got, DefaultLowStockThreshold)
	}

	write(`[1,2]`)
	if got := LowStockThreshold("testwh"); got != DefaultLowStockThreshold {
		t.Fatalf("array = %d, want %d", got, DefaultLowStockThreshold)
	}

	write(`null`)
	if got := LowStockThreshold("testwh"); got != DefaultLowStockThreshold {
		t.Fatalf("null = %d, want %d", got, DefaultLowStockThreshold)
	}

	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("testwh"); got != DefaultLowStockThreshold {
